INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (15, 'Pola jahitan tidak berjalan sesuai program', 'Mesin menjalankan pola dengan bentuk, ukuran, atau urutan jahitan yang tidak sesuai data program.', 'Data pola tidak sesuai, pengaturan pola berubah, atau terjadi masalah pada sistem kontrol dan feeding frame.', 'Periksa nomor dan data pola, verifikasi parameter program, lalu jalankan kembali pola setelah memastikan data yang dipilih benar.', 'Hentikan mesin sebelum memeriksa atau mengubah parameter program.', 'Data spesifikasi JUKI AMS-210EN-1510 dan panduan pemeriksaan umum');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (15, 'Data pola tidak dapat dimasukkan atau dipanggil', 'Pola tidak dapat disimpan, dipanggil, atau digunakan saat proses menjahit.', 'Data pola bermasalah, kapasitas memori tidak mencukupi, atau media penyimpanan eksternal mengalami gangguan.', 'Periksa data pola, kapasitas memori, dan media penyimpanan. Gunakan data pola yang valid dan ulangi proses input atau pemanggilan.', 'Jangan mematikan mesin saat proses penyimpanan atau pemindahan data sedang berlangsung.', 'Data spesifikasi JUKI AMS-210EN-1510 dan panduan pemeriksaan umum');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (15, 'Panjang atau ukuran pola jahitan tidak sesuai', 'Hasil pola lebih besar, lebih kecil, atau dimensinya berbeda dari program.', 'Parameter enlargement/reduction berubah atau pengaturan area dan koordinat pola tidak sesuai.', 'Periksa parameter pembesaran atau pengecilan pola dan pastikan nilai sesuai kebutuhan sebelum menjalankan siklus jahit.', 'Hentikan mesin sebelum mengubah parameter ukuran pola.', 'Data spesifikasi JUKI AMS-210EN-1510 dan panduan pemeriksaan umum');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (15, 'Intermediate presser tidak bekerja dengan normal', 'Intermediate presser tidak mengangkat, turun terlalu tinggi atau rendah, atau tidak mengikuti proses jahitan.', 'Pengaturan posisi intermediate presser tidak sesuai atau mekanisme penggeraknya mengalami gangguan.', 'Periksa pengaturan posisi dan stroke intermediate presser, lalu periksa mekanisme penggeraknya.', 'Matikan mesin sebelum melakukan pemeriksaan pada mekanisme presser.', 'Data spesifikasi JUKI AMS-210EN-1510 dan panduan pemeriksaan umum');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (15, 'Benang sering putus atau ketegangan jahitan tidak stabil', 'Benang putus saat menjahit pola atau hasil ketegangan jahitan berubah-ubah.', 'Threading tidak benar, pengaturan active tension tidak sesuai, jarum atau hook bermasalah, atau jalur benang memiliki hambatan.', 'Periksa jalur benang, kondisi jarum dan hook, kemudian sesuaikan active thread tension sesuai material dan pola.', 'Matikan mesin sebelum memeriksa jarum, hook, atau jalur benang.', 'Data spesifikasi JUKI AMS-210EN-1510 dan panduan pemeriksaan umum');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (15, 'Feeding frame tidak bergerak stabil', 'Frame bergerak tersendat, posisi pola bergeser, atau kain tidak berada pada posisi yang tepat.', 'Mekanisme frame kotor, penggerak frame mengalami gangguan, atau material tidak terpasang dengan benar.', 'Periksa pemasangan material, bersihkan area frame, dan periksa mekanisme penggerak feeding frame.', 'Hentikan mesin sebelum memasukkan tangan ke area feeding frame.', 'Data spesifikasi JUKI AMS-210EN-1510 dan panduan pemeriksaan umum');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (15, 'Jahitan tidak terbentuk atau hook tidak bekerja normal', 'Jahitan tidak terbentuk dengan baik, benang bawah tidak tertarik, atau terdengar suara tidak normal dari area hook.', 'Pemasangan bobbin tidak benar, hook kotor, jarum tidak sesuai, atau timing jarum dan hook tidak tepat.', 'Periksa bobbin, bersihkan area hook, periksa jarum, dan lakukan pemeriksaan timing bila diperlukan.', 'Matikan mesin dan lepaskan sumber daya sebelum membersihkan atau memeriksa area hook.', 'Data spesifikasi JUKI AMS-210EN-1510 dan panduan pemeriksaan umum');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (15, 'Pelumasan atau gerakan mesin tidak normal', 'Mesin bergerak berat, muncul suara tidak normal, atau area hook tidak mendapatkan pelumasan yang memadai.', 'Sistem semi-dry atau minute-quantity lubrication tidak bekerja sesuai kondisi, oli tidak sesuai, atau terdapat kotoran pada mekanisme.', 'Periksa sistem pelumasan pada area hook, gunakan JUKI New Defrix Oil No.2 atau oli setara ISO VG32 sesuai prosedur, dan bersihkan mekanisme yang kotor.', 'Matikan mesin sebelum memeriksa pelumasan atau bagian mekanis yang bergerak.', 'Data spesifikasi JUKI AMS-210EN-1510 dan panduan pemeriksaan umum');
